WITH scored AS (SELECT *, SUM(status_bits) OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_status_bits, NTILE(10) OVER (PARTITION BY device_code ORDER BY status_bits, id) status_bits_bucket FROM device_readings WHERE device_code IN ('DV-01', 'DV-02', 'DV-04')) SELECT id, device_code, temp_c, humidity, status_bits, running_status_bits, status_bits_bucket FROM scored ORDER BY status_bits_bucket DESC NULLS LAST;
